begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
select ok((select rowsecurity from pg_tables where schemaname='public' and tablename='enrollment_invoice_links'),'Enrollment invoice links enforce RLS');
select ok(not has_table_privilege('authenticated','public.enrollment_invoice_links','insert'),'Link creation requires checked commands');
select ok(not has_table_privilege('authenticated','public.enrollment_invoice_links','update'),'Link identity cannot be edited directly');
select ok(not has_function_privilege('anon','public.academic_overview(uuid,jsonb,integer)','execute'),'Anonymous report execution is revoked');
select ok(not has_function_privilege('anon','public.create_enrollment_invoice_draft(uuid,uuid,uuid,integer,text,text,text)','execute'),'Anonymous billing execution is revoked');
create temporary table academic_scope(label text primary key,id uuid);
grant select,insert on academic_scope to authenticated;
create function pg_temp.sid(text) returns uuid language sql stable as $$select id from academic_scope where label=$1$$;
create function pg_temp.day(integer) returns text language sql stable as $$select ((now() at time zone 'Asia/Tashkent')::date+$1)::text$$;
insert into auth.users(id,email,email_confirmed_at) values('99999600-0000-0000-0000-000000000001','native-academic-owner@example.test',now()),('99999600-0000-0000-0000-000000000002','native-academic-teacher@example.test',now()),('99999600-0000-0000-0000-000000000003','native-academic-foreign@example.test',now());
set local role authenticated;
set local request.jwt.claim.sub='99999600-0000-0000-0000-000000000001';
insert into academic_scope values('tenant',public.create_business('Native academic integration'));
insert into academic_scope select 'branch',id from public.branches where tenant_id=pg_temp.sid('tenant') limit 1;
insert into academic_scope values('course',public.save_course(pg_temp.sid('tenant'),null,gen_random_uuid(),0,'{"name":"Academic integration course","standard_price":"750000.10","pricing_model":"monthly"}'));
insert into academic_scope values('group',public.save_study_group(pg_temp.sid('tenant'),null,gen_random_uuid(),0,jsonb_build_object('name','Original student group','course_id',pg_temp.sid('course'),'branch_id',pg_temp.sid('branch'),'start_date',pg_temp.day(-30),'capacity','1')));
insert into academic_scope values('teacher',public.save_employee(pg_temp.sid('tenant'),null,'Native integration teacher','','native-academic-teacher@example.test','Teacher','active',pg_temp.day(0)::date,'',array[pg_temp.sid('branch')]));
insert into academic_scope values('role',(select id from public.business_roles where tenant_id=pg_temp.sid('tenant') and system_key='teacher'));
create temporary table academic_token(token text);
grant select,insert on academic_token to authenticated;
insert into academic_token select public.create_employee_invitation(pg_temp.sid('tenant'),pg_temp.sid('teacher'),pg_temp.sid('role'));
set local request.jwt.claim.sub='99999600-0000-0000-0000-000000000002';
select public.accept_employee_invitation((select token from academic_token));
set local request.jwt.claim.sub='99999600-0000-0000-0000-000000000001';
select public.set_group_teachers(pg_temp.sid('tenant'),pg_temp.sid('group'),gen_random_uuid(),1,array[pg_temp.sid('teacher')],pg_temp.sid('teacher'));
select public.change_group_status(pg_temp.sid('tenant'),pg_temp.sid('group'),gen_random_uuid(),2,'active','Activate original student group');
insert into academic_scope values('student',public.save_student(pg_temp.sid('tenant'),gen_random_uuid(),null,'{"first_name":"Original native student","phone":"9989088181"}','{}',array[pg_temp.sid('branch')]));
insert into academic_scope values('enrollment',public.create_student_enrollment(pg_temp.sid('tenant'),pg_temp.sid('group'),pg_temp.sid('student'),gen_random_uuid(),jsonb_build_object('enrollment_date',pg_temp.day(0),'effective_start_date',pg_temp.day(-10),'status','active','agreed_price','9007199254740993.12','pricing_model','monthly')));
create temporary table academic_values(label text primary key,value jsonb);
grant select,insert on academic_values to authenticated;
insert into academic_values values('filters',jsonb_build_object('from',pg_temp.day(-30),'to',pg_temp.day(30)));
select is(public.academic_overview(pg_temp.sid('tenant'),(select value from academic_values where label='filters'))->'stats'->>'unique_active_students','1','Academic report counts original Student Profiles');
select is(public.academic_overview(pg_temp.sid('tenant'),(select value from academic_values where label='filters'))->'stats'->>'at_capacity','1','Reserved seat capacity is aggregated');
select is(public.student_academic_summary(pg_temp.sid('tenant'),pg_temp.sid('student'))->>'active_groups','1','Original student academic summary works');
select is(public.student_enrollment_directory(pg_temp.sid('tenant'),pg_temp.sid('student'))->'rows'->0->>'customer_id',pg_temp.sid('student')::text,'Enrollment history retains the original customer ID');
insert into academic_scope values('invoice',public.create_enrollment_invoice_draft(pg_temp.sid('tenant'),pg_temp.sid('enrollment'),'99999600-0000-0000-0000-000000000010',1,pg_temp.day(0),pg_temp.day(1),'Explicit monthly charge'));
select is(public.create_enrollment_invoice_draft(pg_temp.sid('tenant'),pg_temp.sid('enrollment'),'99999600-0000-0000-0000-000000000010',1,pg_temp.day(0),pg_temp.day(1),'Explicit monthly charge'),pg_temp.sid('invoice'),'Exact duplicate submission returns one invoice');
select is(public.invoice_details(pg_temp.sid('tenant'),pg_temp.sid('invoice'))->'invoice'->>'state','draft','Integration never automatically issues invoices');
select is(public.invoice_details(pg_temp.sid('tenant'),pg_temp.sid('invoice'))->'invoice'->'items'->0->>'unit_price','9007199254740993.12','Exact-decimal agreement reaches existing invoice service');
select is(public.invoice_details(pg_temp.sid('tenant'),pg_temp.sid('invoice'))->'invoice'->>'customer_id',pg_temp.sid('student')::text,'The original shared contact is the debtor');
select is(public.invoice_enrollment_source(pg_temp.sid('tenant'),pg_temp.sid('invoice'))->>'enrollment_id',pg_temp.sid('enrollment')::text,'Invoice links back to enrollment');
select is(public.student_academic_summary(pg_temp.sid('tenant'),pg_temp.sid('student'))->'invoices'->>'total','1','Student Profile shows linked invoices');
select is(public.customer_financial_profile(pg_temp.sid('tenant'),pg_temp.sid('student'))->'summary'->>'outstanding','0.00','Draft creation does not post debt');
select throws_ok($$delete from public.enrollment_invoice_links$$,'42501',null,'Authenticated users cannot delete retained links');
set local request.jwt.claim.sub='99999600-0000-0000-0000-000000000002';
select is(public.academic_overview(pg_temp.sid('tenant'),(select value from academic_values where label='filters'))->>'total','1','Assigned teacher sees their academic report');
select is(public.enrollment_billing_details(pg_temp.sid('tenant'),pg_temp.sid('enrollment'))->>'total','0','Teacher sees no financial invoice count');
select is(public.enrollment_billing_details(pg_temp.sid('tenant'),pg_temp.sid('enrollment'))->>'can_create','false','Teacher receives no billing authority');
select is((select count(*) from public.enrollment_invoice_links),0::bigint,'Teacher raw source-link reads remain isolated');
select throws_ok($$select public.create_enrollment_invoice_draft(pg_temp.sid('tenant'),pg_temp.sid('enrollment'),gen_random_uuid(),1,pg_temp.day(0),pg_temp.day(1),'Teacher escalation')$$,'42501',null,'Teacher cannot create invoices through academic RPC');
select throws_ok($$select public.student_academic_summary(pg_temp.sid('tenant'),pg_temp.sid('student'))$$,'42501',null,'Academic roster access does not authorize the whole Student Profile');
set local request.jwt.claim.sub='99999600-0000-0000-0000-000000000003';
select throws_ok($$select public.academic_overview(pg_temp.sid('tenant'),(select value from academic_values where label='filters'))$$,'42501',null,'Foreign tenant report ID is rejected');
select throws_ok($$select public.enrollment_billing_details(pg_temp.sid('tenant'),pg_temp.sid('enrollment'))$$,'42501',null,'Foreign enrollment billing ID is rejected');
select is((select count(*) from public.enrollment_invoice_links),0::bigint,'Foreign source-link rows are invisible');
set local request.jwt.claim.sub='';
select throws_ok($$select public.student_academic_summary(pg_temp.sid('tenant'),pg_temp.sid('student'))$$,'42501',null,'Subjectless authenticated requests cannot read student data');
reset role;
select is((select count(*) from public.invoice_receivable_entries where tenant_id=pg_temp.sid('tenant')),0::bigint,'No hidden receivable entries were generated');
set constraints all immediate;
select * from finish();
rollback;
